Generated SPARQL:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:timeHorizon "Long-term" ;
            wm:hasPortfolioHealth ?portfolioHealth .

  ?portfolioHealth wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)

  {
    SELECT ?investor (COUNT(?holding) AS ?global_equity_holding_count)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:investmentType "Global Equity" .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (COUNT(?action) AS ?rebalancing_action_count)
    WHERE {
      ?investor wm:hasRebalancingAction ?action .
    }
    GROUP BY ?investor
  }

  FILTER(?global_equity_holding_count > 0)
  FILTER(?rebalancing_action_count > 0)
}
GROUP BY ?investorId ?investorName

