PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:category "Gold"^^xsd:string .

  ?investor wm:hasPortfolioHealth ?portfolioHealth .
  ?portfolioHealth wm:diversificationScore ?diversificationScore .
  FILTER(?diversificationScore < 50)

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:investmentType "Corporate Bond"^^xsd:string .
  }

  FILTER EXISTS {
    ?investor wm:hasSectorAllocation ?sectorAlloc .
    ?sectorAlloc wm:sector "Automobile"^^xsd:string ;
                 wm:allocationPct ?allocationPct .
    FILTER(?allocationPct > 0)
  }
